const stPillS=s=>`<span class="pill ${s==='Approved'?'blue':s==='In Review'?'warn':''}">${s}</span>`;
function brandKit(ctx){return `${ctx||''}<div class="grid2" style="margin-bottom:20px"><section class="panel" style="padding:20px"><p class="sec-t" style="margin-top:0">Colours</p><div class="grid3" style="gap:12px">${[['Ink','#16171B'],['Signal','#FFC633'],['Volt','#2B63F6']].map(([n,h])=>`<div class="swatch" style="--c:${h}"><i></i><b style="font-size:14px">${n}</b><span class="mono muted" style="font-size:12px">${h}</span></div>`).join('')}</div></section>
<section class="panel" style="padding:20px"><p class="sec-t" style="margin-top:0">Fonts</p><p style="font:700 40px/1 var(--font-d);letter-spacing:-.04em">Aa Bricolage</p><p class="muted" style="margin:6px 0 14px">Headlines</p><p style="font:500 26px/1 var(--font)">Aa Geist</p><p class="muted" style="margin-top:6px">Body and interface</p></section></div>
<div class="grid2"><section class="panel" style="padding:20px"><p class="sec-t" style="margin-top:0">Voice and tone</p><div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:12px">${['Confident','Plain English','Warm','No hype'].map(t=>`<span class="tag">${t}</span>`).join('')}</div><p class="tx2">We sound like a calm expert friend. Short sentences. Real numbers. Never “guru” language.</p><div class="grid2" style="gap:10px;margin-top:14px"><div class="notice blue" style="font-size:13.5px">${ic('check',16)}<span>“Your funnel, done in 30 days.”</span></div><div class="notice danger" style="font-size:13.5px">${ic('x',16)}<span>“10X your income overnight!!”</span></div></div></section>
<section class="panel" style="padding:20px"><p class="sec-t" style="margin-top:0">Logo notes</p><div style="display:flex;gap:16px;align-items:center;margin-bottom:12px">${mark('l2f',72)}<div class="tx2" style="font-size:14px">Keep clear space equal to the “2”. Never stretch or recolour. Placeholder until the real logo file is uploaded.</div></div><button class="btn ghost sm" data-act="toast:Upload needs the backend.">${ic('upload',16)}Upload logo files</button></section></div>`}
function stratEditor(id,back,backLabel){const s=STRAT[org()].find(x=>x[0]===id)||['new','New funnel strategy','Draft','Just now','none'];
return `${focusBar('office',{title:`<b>${s[1]}</b>`,sub:backLabel,back,right:`<span class="savest" id="savest"><i></i>Saved</span>${stPillS(s[2])}<span class="hide-m">${avs(['UM','SN'])}</span><button class="btn ghost sm hide-m" data-act="toast:Draft → In Review → Approved.">Status</button><button class="btn primary sm" data-act="savedoc">Save</button>`})}
<div class="ed-tools" role="toolbar" aria-label="Formatting">${[['undo','Undo','undo'],['redo','Redo','redo']].map(([i,l,c])=>`<button aria-label="${l}" data-act="cmd:${c}">${ic(i,18)}</button>`).join('')}<span class="vs"></span><select class="sel" aria-label="Text style" data-cmd="formatBlock"><option value="p">Normal text</option><option value="h2">Heading</option><option value="h1">Title</option></select><span class="vs"></span>${[['bold','Bold'],['italic','Italic'],['under','Underline','underline'],['ul','Bullet list','insertUnorderedList']].map(([i,l,c])=>`<button aria-label="${l}" data-act="cmd:${c||i}">${ic(i,18)}</button>`).join('')}<button aria-label="Link" data-act="toast:Add a link to any page or record.">${ic('link',18)}</button><span class="vs"></span><button aria-label="Insert linked asset" data-act="toast:Pick an Avatar, Offer, Story or Brand Kit to reference.">${ic('plus',18)}</button></div>
<div class="edbody"><nav class="outline" aria-label="Outline"><p class="over" style="padding:6px 10px">Outline</p>${['Funnel overview','Target audience','Offer and value','Customer journey','Messaging direction','Success criteria'].map(h=>`<button data-act="noop">${h}</button>`).join('')}</nav>
<article class="docpage"><div contenteditable="true" id="doced" spellcheck="true"><h1>${s[1]}</h1><p class="muted">Started from the template. Change anything; nothing here is required.</p><h2>Funnel overview</h2><p>A quiz funnel that books discovery calls for coaches doing $5k a month, sold as a done-for-you build in 30 days.</p><h2>Target audience</h2><p>Primary avatar: <b>Clara, the stuck coach</b>. She’s great at coaching but hates selling in DMs.</p><h2>Offer and value</h2><ul><li>Funnel Done-For-You, $3,000</li><li>Promise: a finished funnel that books calls in 30 days</li></ul><h2>Customer journey</h2><p>Instagram reel → quiz → personalised result → booking page → discovery call → proposal.</p><h2>Messaging direction</h2><p>Lead with “clients on autopilot”, prove it with the 41-call case study, answer “I tried funnels before”.</p><h2>Success criteria</h2><p>40 booked calls in the first 60 days, 25% close rate.</p></div></article>
<aside class="side-panel" style="display:grid;gap:14px;position:sticky;top:130px"><section class="panel" style="padding:16px"><p class="sec-t" style="margin-top:0">${ic('map',16)}Funnel map</p>${s[4]==='linked'?`<div class="linkrow" style="background:var(--sunk);padding:10px">${plate(app('fmp'),36)}<span class="main"><b>DFY quiz funnel map</b><small>In Funnel Mapper Pro</small></span></div><button class="btn ghost full sm" style="margin-top:8px" data-act="toast:Opens this map in Funnel Mapper Pro.">Open in Funnel Mapper Pro</button><p class="hint" style="margin-top:8px">A link only. The map isn’t copied or synced.</p>`:`<p class="tx2" style="font-size:14px">No map linked yet.</p><button class="btn ghost full sm" style="margin-top:8px" aria-disabled="true" data-act="toast:Linking to Funnel Mapper Pro is pending. The connection hasn’t been built yet.">Start mapping in Funnel Mapper Pro</button><p class="hint" style="margin-top:8px">Map linking is pending. It isn’t built yet.</p>`}</section>
<section class="panel" style="padding:16px"><p class="sec-t" style="margin-top:0">${ic('link',16)}Linked assets</p>${[['avatar','Clara, the stuck coach','Avatar'],['offer','Funnel Done-For-You','Offer'],['story','From 0 to 41 booked calls','Story'],['brand','Brand Kit','Brand Kit']].map(([i,n,t])=>`<div class="linkrow" style="min-height:48px;padding:6px">${ic(i,18)}<span class="main"><b style="font-size:13.5px">${n}</b><small>${t} · reference</small></span></div>`).join('')}<button class="linkbtn" style="font-size:13.5px" data-act="toast:Choose records from this organization only.">+ Link an asset</button></section>
<section class="panel" style="padding:16px;background:var(--sunk);box-shadow:none"><p class="sec-t" style="margin-top:0">${ic('lock',16)}Internal notes · never shared</p><p class="hint">Keep pricing experiments here.</p></section></aside></div>`}

Object.assign(ACT,{savedoc:()=>{const s=$('#savest');if(s){s.classList.remove('dirty');s.innerHTML='<i></i>Saved just now'}toast('Saved.','ok',1500)},cmd:v=>{document.execCommand(v,false,null);$('#doced')?.focus()}});
INPUT.doced=()=>{const s=$('#savest');if(s){s.classList.add('dirty');s.innerHTML='<i></i>Unsaved changes'}};
document.addEventListener('change',e=>{if(e.target.dataset.cmd){document.execCommand('formatBlock',false,e.target.value);$('#doced')?.focus()}});
